const fields=(value:string)=>value.split(";");
const firstSentence=(value:string)=>value.match(/^.{40,}?[.!?](?=\s|$)/)?.[0]??value;
export const providerProfilesSeventh:Record<string,ProviderProfile>=Object.fromEntries(Object.entries(rows).map(([name,[officialUrl,de,en,fd,fe,rd,re]])=>[name,{
  officialUrl,officialLabel:{de:`Offizielle Anbieterquelle: ${name}`,en:`Official provider source: ${name}`},
  metaDescription:{de:firstSentence(de),en:firstSentence(en)},
  summary:{de:`${de} ${detail[name][0]}`,en:`${en} ${detail[name][1]}`},focus:{de:fields(fd),en:fields(fe)},buyerGroups:{de:fields(rd),en:fields(re)}
}]));
